 <div class="overlay hidden" id="endScreen"><section class="card"><div class="eyebrow" id="endEyebrow">THE CITY REMEMBERS</div><h1 id="endTitle">DAWN<span>BREAKS</span></h1><p class="description" id="endText">The rain finally lets go.</p><div class="actions"><button class="startbtn" id="againBtn">RUN IT BACK&nbsp; ↗</button></div></section></div><div class="toast" id="toast">PERFECT DEFLECT</div>
 <div class="touch"><div class="touchgroup"><button data-key="a">◀</button><button data-key="d">▶</button></div><div class="touchgroup"><button data-key="space">JUMP</button><button data-key="k">PARRY</button><button data-key="j">CUT</button><button data-key="l">DASH</button></div></div>
 </main>
 <script>
+(()=>{
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
+const $=s=>document.querySelector(s), W=2400, G=760;
+let vw=0,vh=0,dpr=1,scale=1,cam=0,last=0,elapsed=0,started=false,ended=false,won=false,shake=0,flash=0;
+const keys=new Set(),particles=[],rain=[];
+const platforms=[{x:0,w:430,y:520},{x:500,w:390,y:470},{x:965,w:370,y:530},{x:1405,w:390,y:460},{x:1865,w:535,y:520}];
+const shards=[{x:330,y:470,taken:false},{x:1110,y:480,taken:false},{x:2035,y:470,taken:false}];
+const player={x:85,y:520,vx:0,vy:0,w:30,h:58,hp:100,posture:0,face:1,ground:true,attack:0,parry:0,dash:0,inv:0,dead:false,trail:[]};
+const enemy={x:726,y:470,vx:0,hp:100,max:100,posture:0,phase:'idle',timer:1.5,face:-1,alive:true,stun:0,attackCD:0};
+const goalX=2255;
+function resize(){const r=canvas.getBoundingClientRect();vw=r.width;vh=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);scale=vh/760;}
+new ResizeObserver(resize).observe(canvas);resize();
+function rand(n){return Math.random()*n}
+for(let i=0;i<130;i++)rain.push({x:rand(1600),y:rand(900),s:rand(8)+7,v:rand(330)+270});
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
+function onGround(x,y){return platforms.find(p=>x>p.x-14&&x<p.x+p.w+14&&y>=p.y-2&&y<=p.y+20)}
+function input(e,down){let k=e.key?.toLowerCase();if(k==='arrowleft')k='a';if(k==='arrowright')k='d';if(k==='arrowup'||k===' ')k='space';if(k==='arrowdown')k='s';if(down){keys.add(k);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key))e.preventDefault()}else keys.delete(k)}
+window.addEventListener('keydown',e=>{input(e,true);if(e.repeat)return;if(!started&&e.key==='Enter')begin();if(e.key.toLowerCase()==='j')attack();if(e.key.toLowerCase()==='k')parry();if(e.key.toLowerCase()==='l')dash();if(e.key.toLowerCase()==='f')deathblow()});window.addEventListener('keyup',e=>input(e,false));
+document.querySelectorAll('.touch button').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(k);if(k==='j')attack();if(k==='k')parry();if(k==='l')dash()});for(const ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>keys.delete(k))});
+$('#startBtn').onclick=begin;$('#againBtn').onclick=()=>location.reload();
+function begin(){started=true;$('#intro').classList.add('hidden');last=performance.now();}
+function toast(t){const el=$('#toast');el.textContent=t;el.classList.remove('show');void el.offsetWidth;el.classList.add('show')}
+function particle(x,y,color,n=8,power=180){for(let i=0;i<n;i++){let a=rand(Math.PI*2),v=rand(power);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.35+rand(.45),max:.8,color,size:1+rand(3)})}}
+function attack(){if(!started||ended||player.attack>0||player.dash>0)return;player.attack=.25;player.vx+=player.face*55;}
+function parry(){if(!started||ended)return;player.parry=.24}
+function dash(){if(!started||ended||player.dash>0)return;player.dash=.18;player.inv=.24;player.vx=player.face*620;particle(player.x,player.y-28,'#73f7e8',5,60)}
+function deathblow(){if(enemy.alive&&enemy.posture>=100&&Math.abs(enemy.x-player.x)<83){enemy.alive=false;enemy.hp=0;particle(enemy.x,enemy.y-30,'#ffb66d',28,260);shake=15;toast('DEATHBLOW');$('#enemyUI').classList.remove('active')}}
+function hurt(n){if(player.inv>0)return;player.hp=Math.max(0,player.hp-n);player.inv=.8;shake=9;particle(player.x,player.y-25,'#ff6677',12,180);if(player.hp<=0){player.dead=true;finish(false)}}
+function finish(v){ended=true;won=v;setTimeout(()=>{$('#endEyebrow').textContent=v?'THE CITY REMEMBERS':'THE NIGHT TAKES YOU';$('#endTitle').innerHTML=v?'DAWN<span>BREAKS</span>':'SHADOW<span>FALLS</span>';$('#endText').textContent=v?'Three memories restored. The city has a future — because you gave it one.':'Even legends bleed. The rooftops will still be here when you are ready.';$('#endScreen').classList.remove('hidden')},900)}
+function update(dt){if(!started||ended)return;elapsed+=dt;
+ player.attack=Math.max(0,player.attack-dt);player.parry=Math.max(0,player.parry-dt);player.dash=Math.max(0,player.dash-dt);player.inv=Math.max(0,player.inv-dt);
+ const dir=(keys.has('d')?1:0)-(keys.has('a')?1:0);if(dir){player.face=dir;if(player.dash<=0)player.vx+=dir*210*dt}if(player.dash<=0)player.vx*=Math.pow(player.ground?.78:.92,dt*60);player.vx=clamp(player.vx,-280,280);
+ if((keys.has('space')||keys.has('w'))&&player.ground){player.vy=-540;player.ground=false;particle(player.x,player.y,'#9bced0',5,80)}
+ if(player.dash<=0)player.vy+=1450*dt;
+ let oldY=player.y;player.x=clamp(player.x+player.vx*dt,8,W-22);player.y+=player.vy*dt;player.ground=false;
+ for(const p of platforms)if(player.vy>=0&&oldY<=p.y&&player.y>=p.y&&player.x+12>p.x&&player.x-12<p.x+p.w){player.y=p.y;player.vy=0;player.ground=true;break}
+ if(player.y>vh/scale+100){hurt(100);player.y=520;player.vy=0}
+ if(player.attack>0&&enemy.alive&&Math.abs(player.x-enemy.x)<63&&Math.abs(player.y-enemy.y)<32&&player.face===Math.sign(enemy.x-player.x)){enemy.hp=Math.max(0,enemy.hp-23);enemy.posture=clamp(enemy.posture+31,0,100);enemy.stun=.38;enemy.phase='stun';enemy.timer=.38;particle(enemy.x,enemy.y-32,'#ffd484',12,180);shake=5;player.attack=0;if(enemy.hp<=0){enemy.alive=false;toast('TARGET DOWN');$('#enemyUI').classList.remove('active')}}
+ // rooftop guards: a clear tell, then a short-range strike that can be deflected
+ if(enemy.alive){$('#enemyUI').classList.add('active');$('#enemyBar').style.width=`${enemy.hp}%`;enemy.face=Math.sign(player.x-enemy.x)||-1;enemy.attackCD=Math.max(0,enemy.attackCD-dt);
+ const dist=Math.abs(player.x-enemy.x);
+ if(enemy.phase==='idle'){if(dist<240){enemy.vx=clamp((player.x-enemy.x)*1.25,-90,90);enemy.x+=enemy.vx*dt}if(dist<100&&enemy.attackCD<=0){enemy.phase='windup';enemy.timer=.67;enemy.vx=0}}
+ else if(enemy.phase==='windup'){enemy.timer-=dt;if(enemy.timer<.35&&Math.random()<dt*12)particle(enemy.x+enemy.face*30,enemy.y-42,'#ff6878',1,20);if(enemy.timer<=0){if(dist<75){if(player.parry>0){enemy.posture=clamp(enemy.posture+48,0,100);enemy.phase='stun';enemy.timer=.72;particle((player.x+enemy.x)/2,player.y-35,'#c7fff6',22,250);shake=8;toast('PERFECT DEFLECT')}else hurt(18)}enemy.phase='recover';enemy.timer=.68;enemy.attackCD=1.1}}
+ else{enemy.timer-=dt;if(enemy.phase==='stun')enemy.posture=Math.max(0,enemy.posture-dt*5);if(enemy.timer<=0)enemy.phase='idle'}
+ if(enemy.posture>=100){enemy.phase='stun';enemy.timer=2;$('#prompt').classList.add('show')}else $('#prompt').classList.remove('show');$('#enemyBar').style.width=`${enemy.hp}%`;
+ }
+ for(const s of shards)if(!s.taken&&Math.abs(s.x-player.x)<35&&Math.abs(s.y-player.y)<65){s.taken=true;particle(s.x,s.y,'#ffce7e',20,200);$('#shardCount').textContent=shards.filter(a=>a.taken).length;toast('MEMORY RESTORED')}
+ if(player.x>goalX&&player.ground){if(shards.every(s=>s.taken))finish(true);else{$('#objectiveTitle').textContent='SHARDS REMAIN';$('#objectiveText').textContent=`${shards.filter(s=>!s.taken).length} MEMORY SIGNALS UNCLAIMED`}}
+ if(player.x<goalX-70){$('#objectiveTitle').textContent='REACH THE SIGNAL';$('#objectiveText').textContent='CROSS THE ROOFTOPS · CLAIM THE SHARDS'}
+ particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=360*dt;p.life-=dt});for(let i=particles.length-1;i>=0;i--)if(particles[i].life<=0)particles.splice(i,1);
+ cam=clamp(player.x-vw/scale*.42,0,W-vw/scale);shake=Math.max(0,shake-dt*24);flash=Math.max(0,flash-dt*2);$('#hpBar').style.width=player.hp+'%';$('#hpText').textContent=Math.ceil(player.hp);$('#postureBar').style.width=enemy.posture+'%';$('#postureText').textContent=enemy.posture>65?'BREAKING':enemy.posture?'BUILDING':'READY';$('#clock').textContent='02:'+String(17+Math.floor(elapsed/12)).padStart(2,'0')+' AM  /  RAINFALL';
+}

input.newString:
$('#clock').textContent='02:'+String(17+Math.floor(elapsed/12)).padStart(2,'0')+' AM  /  RAINFALL';
}
function rr(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){const sw=vw/scale,sh=vh/scale;ctx.setTransform(dpr*scale,0,0,dpr*scale,0,0);ctx.clearRect(0,0,sw,sh);
 let bg=ctx.createLinearGradient(0,0,0,sh);bg.addColorStop(0,'#081622');bg.addColorStop(.58,'#142d39');bg.addColorStop(1,'#213b45');ctx.fillStyle=bg;ctx.fillRect(0,0,sw,sh);
 // distant haze and moon glow
 let glow=ctx.createRadialGradient(sw*.78,sh*.28,5,sw*.78,sh*.28,250);glow.addColorStop(0,'#87d9d733');glow.addColorStop(1,'#7bd8d000');ctx.fillStyle=glow;ctx.fillRect(0,0,sw,sh);
 ctx.save();ctx.translate(-cam*.19,0);
 for(let i=0;i<36;i++){let x=i*102-80,seed=(i*17+3)%11,h=150+seed*22,w=62+(i%3)*15,y=510-h;ctx.fillStyle=i%4===0?'#142d39':'#102631';ctx.fillRect(x,y,w,h);ctx.fillStyle='#294653';ctx.fillRect(x,y,w,3);for(let wy=y+14;wy<510;wy+=19)for(let wx=x+9;wx<x+w-4;wx+=14){if(((Math.floor(wx)+Math.floor(wy)*7+i*13)%6)<3){ctx.fillStyle=((wx+wy)%4<1)?'#e5b97788':'#6dc7c866';ctx.fillRect(wx,wy,5,8)}}if(i%6===2){ctx.fillStyle='#5bf3e877';ctx.fillRect(x+w*.6,y-9,3,9)}}
 ctx.restore();
 // rolling low cloud bands
 for(let i=0;i<5;i++){let x=((i*230-elapsed*8)%(sw+300))-100;ctx.fillStyle='#c5eff0';ctx.globalAlpha=.035;ctx.beginPath();ctx.ellipse(x,230+i*56,150,20,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 ctx.save();let sx=(Math.random()-.5)*shake,sy=(Math.random()-.5)*shake;ctx.translate(sx,sy);ctx.translate(-cam,0);
 // city-level facade silhouettes
 for(let i=0;i<15;i++){let x=i*180-30,h=90+(i*47%165),y=G-h;ctx.fillStyle=i%2?'#0c202a':'#102631';ctx.fillRect(x,y,145,h);ctx.fillStyle='#1b3b44';ctx.fillRect(x,y,145,4);for(let j=0;j<7;j++){ctx.fillStyle=(j+i)%3?'#98e6d322':'#ffd78b33';ctx.fillRect(x+12+j*18,y+18,7,h-25)}}
 // platforms with wet ledges
 for(const p of platforms){let g=ctx.createLinearGradient(0,p.y,0,p.y+260);g.addColorStop(0,'#24404a');g.addColorStop(.035,'#101f28');g.addColorStop(1,'#09131a');ctx.fillStyle=g;ctx.fillRect(p.x,p.y,p.w,G-p.y+160);ctx.fillStyle='#a1d9d8';ctx.fillRect(p.x,p.y,p.w,3);ctx.fillStyle='#5a777b';ctx.fillRect(p.x,p.y+4,p.w,2);for(let x=p.x+12;x<p.x+p.w-5;x+=37){ctx.fillStyle='#29434a';ctx.fillRect(x,p.y+22,19,3)}
 // rooftop antenna and vent details
 for(let x=p.x+65;x<p.x+p.w-45;x+=145){ctx.fillStyle='#192e36';ctx.fillRect(x,p.y-21,35,21);ctx.fillStyle='#3f6268';ctx.fillRect(x+4,p.y-19,27,3);ctx.fillStyle='#789799';ctx.fillRect(x+9,p.y-15,2,12);ctx.fillRect(x+24,p.y-15,2,12)}
 }
 // hanging signs
 for(const x of [165,600,1080,1520,1970]){ctx.fillStyle='#192f38';ctx.fillRect(x,G-102,4,36);ctx.fillStyle='#14303a';ctx.fillRect(x-13,G-68,66,23);ctx.strokeStyle='#54e5d077';ctx.strokeRect(x-13,G-68,66,23);ctx.fillStyle='#70f7e8';ctx.font='bold 10px sans-serif';ctx.fillText('夜 • 09',x-4,G-53);ctx.shadowBlur=15;ctx.shadowColor='#65fff0';ctx.fillStyle='#70f7e899';ctx.fillRect(x-12,G-67,1,20);ctx.shadowBlur=0}
 // memory shards
 for(const s of shards)if(!s.taken){let bob=Math.sin(elapsed*3+s.x)*7;ctx.save();ctx.translate(s.x,s.y+bob);ctx.rotate(elapsed*.8);ctx.shadowColor='#ffd27e';ctx.shadowBlur=22;ctx.fillStyle='#ffe2a1';ctx.beginPath();ctx.moveTo(0,-18);ctx.lineTo(11,0);ctx.lineTo(0,16);ctx.lineTo(-11,0);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff5cb';ctx.lineWidth=1;ctx.stroke();ctx.restore();ctx.strokeStyle='#ffcd7a33';ctx.beginPath();ctx.ellipse(s.x,s.y+19,22+Math.sin(elapsed*3)*3,5,0,0,Math.PI*2);ctx.stroke()}
 drawEnemy();drawPlayer();
 // exit beacon
 ctx.fillStyle='#182f39';ctx.fillRect(goalX,445,8,75);ctx.shadowColor='#ffca72';ctx.shadowBlur=20;ctx.fillStyle='#ffca72';ctx.beginPath();ctx.arc(goalX+4,442,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#f9d99d';ctx.font='9px monospace';ctx.fillText('SIGNAL',goalX-15,430);
 // particles
 for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size)}ctx.globalAlpha=1;
 ctx.restore();
 // rain foreground
 ctx.strokeStyle='#b9e8ef';ctx.lineWidth=1;ctx.globalAlpha=.24;for(const r of rain){let x=(r.x+elapsed*75)%sw,y=(r.y+elapsed*r.v)%sh;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+11);ctx.stroke()}ctx.globalAlpha=1;
 // occasional lightning flicker
 if(Math.random()<.001)flash=.15;if(flash>0){ctx.fillStyle=`rgba(174,235,255,${flash*.28})`;ctx.fillRect(0,0,sw,sh)}
}
function drawPlayer(){let p=player;ctx.save();ctx.translate(p.x,p.y);if(p.face<0)ctx.scale(-1,1);if(p.inv>0&&Math.floor(elapsed*22)%2===0)ctx.globalAlpha=.45;
 // shadow
 ctx.fillStyle='#02090bb5';ctx.beginPath();ctx.ellipse(0,1,22,4,0,0,Math.PI*2);ctx.fill();
 // coat silhouette
 ctx.fillStyle='#111d25';ctx.beginPath();ctx.moveTo(-9,-42);ctx.lineTo(8,-43);ctx.lineTo(15,-8);ctx.lineTo(27,-2);ctx.lineTo(11,0);ctx.lineTo(-10,-5);ctx.lineTo(-19,0);ctx.lineTo(-12,-27);ctx.closePath();ctx.fill();
 ctx.fillStyle='#263a42';ctx.fillRect(-8,-44,16,23);ctx.fillStyle='#d9b891';ctx.fillRect(-5,-52,11,11);ctx.fillStyle='#152630';ctx.fillRect(-7,-57,16,6);ctx.fillStyle='#73f7e8';ctx.fillRect(3,-48,5,2);ctx.fillStyle='#ec596d';ctx.fillRect(-8,-46,17,3);
 // legs
 ctx.strokeStyle='#1a2a31';ctx.lineWidth=6;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-5,-11);ctx.lineTo(-8,-1);ctx.moveTo(7,-12);ctx.lineTo(11,-1);ctx.stroke();
 // scarf in wind
 ctx.fillStyle='#e65d70';ctx.beginPath();ctx.moveTo(-4,-47);ctx.lineTo(-19,-42);ctx.lineTo(-30+Math.sin(elapsed*8)*5,-32);ctx.lineTo(-11,-37);ctx.closePath();ctx.fill();
 // blade drawn during swing or resting
 ctx.save();if(p.attack>0){ctx.rotate(-.8+((.25-p.attack)/.25)*1.25)}ctx.strokeStyle='#bdeee9';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(7,-29);ctx.lineTo(30,-43);ctx.stroke();ctx.strokeStyle='#f9e3b4';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(4,-30);ctx.lineTo(12,-25);ctx.stroke();if(p.attack>0){ctx.strokeStyle='#9ffff4aa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(4,-29,41,-.8,.65);ctx.stroke()}if(p.parry>0){ctx.strokeStyle='#c8fff4';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-30,39,-1.35,.6);ctx.stroke()}ctx.restore();ctx.restore()}
function drawEnemy(){if(!enemy.alive)return;ctx.save();ctx.translate(enemy.x,enemy.y);if(enemy.face<0)ctx.scale(-1,1);ctx.fillStyle='#030a0cb5';ctx.beginPath();ctx.ellipse(0,1,23,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#25242a';ctx.beginPath();ctx.moveTo(-12,-42);ctx.lineTo(12,-42);ctx.lineTo(18,-2);ctx.lineTo(-16,-2);ctx.closePath();ctx.fill();ctx.fillStyle='#40434a';ctx.fillRect(-10,-48,20,11);ctx.fillStyle='#171d25';ctx.fillRect(-12,-56,24,10);ctx.fillStyle='#ff6a73';ctx.fillRect(2,-50,8,2);ctx.fillStyle='#141b20';ctx.fillRect(-9,-20,18,4);ctx.strokeStyle='#babcb6';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(8,-32);ctx.lineTo(32,-40);ctx.stroke();if(enemy.phase==='windup'){ctx.shadowColor='#ff516b';ctx.shadowBlur=19;ctx.fillStyle='#ff6677';ctx.beginPath();ctx.arc(17,-42,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ff667799';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-29,31,-1.2,.6);ctx.stroke()}if(enemy.phase==='stun'){ctx.fillStyle='#ffcf79';ctx.font='bold 14px sans-serif';ctx.fillText('✦',-4,-67)}ctx.restore()}

